mapper.select:
SELECT , IFNULL(su_stu.real_name, su_stu.username) AS stu_name, su_stu.avatar AS stu_avatar, s.student_no AS stu_no, s.class_name AS class_name, s.grade AS grade, s.major AS major, IFNULL(su_tch.real_name, su_tch.username) AS teacher_name, t.teacher_no AS teacher_no, t.department AS teacher_dept, t.title AS teacher_title, t.specialty AS teacher_spec, su_tch.avatar AS teacher_avatar FROM my_question_answer qa LEFT JOIN my_student s ON s.stu_id = qa.stu_id LEFT JOIN my_sys_user su_stu ON su_stu.user_id = s.user_id LEFT JOIN my_teacher t ON t.teacher_id = qa.teacher_id LEFT JOIN my_sys_user su_tch ON su_tch.user_id = t.user_id
AND qa.stu_id = #{stuId} AND qa.teacher_id = #{teacherId} AND qa.status = #{status}
ORDER BY qa.create_time DESC

mapper.update:
UPDATE my_question_answer
answer = #{answer}, status = #{status}, update_by = #{updateBy}, update_time = #{updateTime},
WHERE id = #{id}

UPDATE my_question_answer
question = #{question}, answer = #{answer}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime},
WHERE id = #{id}
